class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        FULL = (1 << 17) - 1
        m = len(andValues)
        dp = [dict() for _ in range(m + 1)]
        dp[0][FULL] = 0
        for x in nums:
            nd = [dict() for _ in range(m + 1)]
            for j in range(m + 1):
                for v, c in dp[j].items():
                    nv = v & x
                    if nv not in nd[j] or nd[j][nv] > c:
                        nd[j][nv] = c
                    if j < m and nv == andValues[j]:
                        if FULL not in nd[j+1] or nd[j+1][FULL] > c + x:
                            nd[j+1][FULL] = c + x
            dp = nd
        return min(dp[m].values()) if dp[m] else -1

