class Solution {
public:
    int minimumValueSum(vector<int>& nums, vector<int>& andValues) {
        const int FULL = (1 << 17) - 1;
        int n = nums.size(), m = andValues.size();
        vector<unordered_map<int,long long>> dp(m + 1);
        dp[0][FULL] = 0;
        for (int x : nums) {
            vector<unordered_map<int,long long>> nd(m + 1);
            for (int j = 0; j <= m; j++)
                for (auto& [v, c] : dp[j]) {
                    int nv = v & x;
                    auto it = nd[j].find(nv);
                    if (it == nd[j].end() || it->second > c) nd[j][nv] = c;
                    if (j < m && nv == andValues[j]) {
                        auto it2 = nd[j+1].find(FULL);
                        if (it2 == nd[j+1].end() || it2->second > c + x) nd[j+1][FULL] = c + x;
                    }
                }
            dp = move(nd);
        }
        if (dp[m].empty()) return -1;
        long long ans = LLONG_MAX;
        for (auto& [v, c] : dp[m]) ans = min(ans, c);
        return ans;
    }
};

