class Solution {
    public int minimumValueSum(int[] nums, int[] andValues) {
        final int FULL = (1 << 17) - 1;
        int m = andValues.length;
        List<Map<Integer, Long>> dp = new ArrayList<>();
        for (int j = 0; j <= m; j++) dp.add(new HashMap<>());
        dp.get(0).put(FULL, 0L);
        for (int x : nums) {
            List<Map<Integer, Long>> nd = new ArrayList<>();
            for (int j = 0; j <= m; j++) nd.add(new HashMap<>());
            for (int j = 0; j <= m; j++)
                for (var e : dp.get(j).entrySet()) {
                    int nv = e.getKey() & x; long c = e.getValue();
                    nd.get(j).merge(nv, c, Math::min);
                    if (j < m && nv == andValues[j])
                        nd.get(j + 1).merge(FULL, c + x, Math::min);
                }
            dp = nd;
        }
        return dp.get(m).isEmpty() ? -1 :
            (int)(long) dp.get(m).values().stream().min(Long::compare).get();
    }
}

