var minimumValueSum = function(nums, andValues) {
    const FULL = (1 << 17) - 1;
    const m = andValues.length;
    let dp = Array.from({length: m + 1}, () => new Map());
    dp[0].set(FULL, 0);
    for (const x of nums) {
        const nd = Array.from({length: m + 1}, () => new Map());
        for (let j = 0; j <= m; j++)
            for (const [v, c] of dp[j]) {
                const nv = v & x;
                if (!nd[j].has(nv) || nd[j].get(nv) > c) nd[j].set(nv, c);
                if (j < m && nv === andValues[j]) {
                    if (!nd[j+1].has(FULL) || nd[j+1].get(FULL) > c + x)
                        nd[j+1].set(FULL, c + x);
                }
            }
        dp = nd;
    }
    return dp[m].size ? Math.min(...dp[m].values()) : -1;
};

