class Solution {
    int n, m;
    vector<int>* nums_; vector<int>* av_;
    map<tuple<int,int,int>, long long> memo;
    long long f(int i, int j, int v) {
        if (j == m) return i == n ? 0 : LLONG_MAX;
        if (i == n) return LLONG_MAX;
        auto key = make_tuple(i, j, v);
        auto it = memo.find(key);
        if (it != memo.end()) return it->second;
        int nv = v & (*nums_)[i];
        long long best = f(i + 1, j, nv);
        if (nv == (*av_)[j]) {
            long long sub = f(i + 1, j + 1, ~0);
            if (sub != LLONG_MAX) best = min(best, (long long)(*nums_)[i] + sub);
        }
        return memo[key] = best;
    }
public:
    int minimumValueSum(vector<int>& nums, vector<int>& andValues) {
        n = nums.size(); m = andValues.size();
        nums_ = &nums; av_ = &andValues;
        long long ans = f(0, 0, ~0);
        return ans == LLONG_MAX ? -1 : (int) ans;
    }
};

