class Solution {
    private int[] nums, av;
    private int n, m;
    private Map<Long, Long> memo;
    private long f(int i, int j, int v) {
        if (j == m) return i == n ? 0 : Long.MAX_VALUE;
        if (i == n) return Long.MAX_VALUE;
        long key = ((long) i << 40) | ((long) j << 32) | (v & 0xffffffffL);
        Long got = memo.get(key);
        if (got != null) return got;
        int nv = v & nums[i];
        long best = f(i + 1, j, nv);
        if (nv == av[j]) {
            long sub = f(i + 1, j + 1, -1);
            if (sub != Long.MAX_VALUE) best = Math.min(best, (long) nums[i] + sub);
        }
        memo.put(key, best);
        return best;
    }
    public int minimumValueSum(int[] nums, int[] andValues) {
        this.nums = nums; this.av = andValues;
        n = nums.length; m = andValues.length;
        memo = new HashMap<>();
        long ans = f(0, 0, -1);
        return ans == Long.MAX_VALUE ? -1 : (int) ans;
    }
}

