var minimumValueSum = function(nums, andValues) {
    const n = nums.length, m = andValues.length;
    const memo = new Map();
    const INF = Infinity;
    const f = (i, j, v) => {
        if (j === m) return i === n ? 0 : INF;
        if (i === n) return INF;
        const key = i * 1e12 + j * 1e6 + (v >>> 0);
        if (memo.has(key)) return memo.get(key);
        const nv = v & nums[i];
        let best = f(i + 1, j, nv);
        if (nv === andValues[j]) {
            const sub = f(i + 1, j + 1, -1);
            if (sub !== INF) best = Math.min(best, nums[i] + sub);
        }
        memo.set(key, best);
        return best;
    };
    const ans = f(0, 0, -1);
    return ans === INF ? -1 : ans;
};
